 * Longest common subsequence diffing between a base document and one side.
 *
 * Produces the runs of base lines that a side replaces with its own lines,
 * using the tie-breaking rule from the specification: when reconstructing
 * the LCS path, advance the side whose remaining subsequence length is at
 * least as long as the other's, preferring to advance the base on a tie.
 */

/**
 * Compute the changes needed to turn `base` into `side`.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @returns {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]}
 */
export function computeChanges(base, side) {
  const m = base.length
  const n = side.length

  // L[i][j] holds the length of the LCS of base[i:] and side[j:].
  const lcsLength = new Array(m + 1)
  for (let i = 0; i <= m; i++) lcsLength[i] = new Uint32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      lcsLength[i][j] = base[i] === side[j]
        ? lcsLength[i + 1][j + 1] + 1
        : Math.max(lcsLength[i + 1][j], lcsLength[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let gapBaseStart = 0
  let gapSideStart = 0

  const closeGap = () => {
    if (i > gapBaseStart || j > gapSideStart) {
      changes.push({ baseStart: gapBaseStart, baseEnd: i, sideStart: gapSideStart, sideEnd: j })
    }
    gapBaseStart = i
    gapSideStart = j
  }

  while (i < m || j < n) {
    if (i < m && j < n && base[i] === side[j]) {
      closeGap()
      i++
      j++
      gapBaseStart = i
      gapSideStart = j
      continue
    }
    if (j >= n) {
      i++
    } else if (i >= m) {
      j++
    } else if (lcsLength[i + 1][j] >= lcsLength[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  closeGap()

  return changes
}
"}

