 * Split the base document into an ordered list of regions covering it end
 * to end, each either stable (untouched by either side) or touched by one
 * or more changes from either side.
 */
function buildRegionGroups(mineChanges, theirsChanges, baseLength) {
  const tagged = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirsChanges.map(c => ({ ...c, side: 'theirs' })),
  ].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  for (const change of tagged) {
    const last = groups[groups.length - 1]
    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const regions = []
  let pos = 0
  for (const group of groups) {
    if (group.start > pos) regions.push({ type: 'stable', start: pos, end: group.start })
    regions.push({ type: 'changed', start: group.start, end: group.end, changes: group.changes })
    pos = group.end
  }
  if (pos < baseLength) regions.push({ type: 'stable', start: pos, end: baseLength })

  return regions
}

