 * Reconstruct one side's lines for a changed region: the side's own change
 * lines where it made a change, and the base's lines everywhere else in
 * the region.
 */
function reconstructSide(region, base, sideArray, sideName) {
  const sideChanges = region.changes
    .filter(c => c.side === sideName)
    .sort((a, b) => a.baseStart - b.baseStart)
  if (sideChanges.length === 0) return base.slice(region.start, region.end)

  const out = []
  let pos = region.start
  for (const change of sideChanges) {
    out.push(...base.slice(pos, change.baseStart))
    out.push(...sideArray.slice(change.sideStart, change.sideEnd))
    pos = change.baseEnd
  }
  out.push(...base.slice(pos, region.end))
  return out
}

