 * Resolve a changed region into one of: `both` (the sides made the same
 * change), `mine` or `theirs` (only that side changed it) or `conflict`.
 */
function resolveRegion(region, mine, base, theirs) {
  const mineLines = reconstructSide(region, base, mine, 'mine')
  const theirsLines = reconstructSide(region, base, theirs, 'theirs')
  const baseLines = base.slice(region.start, region.end)

  if (linesEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines, mineLines, baseLines, theirsLines }
  if (linesEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines, mineLines, baseLines, theirsLines }
  if (linesEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines, mineLines, baseLines, theirsLines }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
