  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegionGroups(mineChanges, theirsChanges, base.length)

  return regions.map(region => {
    if (region.type === 'stable') return { kind: 'stable', lines: base.slice(region.start, region.end) }
    return resolveRegion(region, mine, base, theirs)
  })
